#!/usr/bin/env bash
# install-forwarder.sh — Spec 080 Phase C: install the VM tailnet
# forwarder as a systemd unit on VM port 8001 (run ONLY in a CLEAR
# wave window; it writes /etc and /var/lib).
# - Unit: the staged draft (glossa-tailnet-forwarder.service) plus an
#   EnvironmentFile line, generated by sed so the draft stays canonical.
# - Env file: /var/lib/glossa-lab/forwarder.env (mode 0600) carrying
#   HTTPS_PROXY copied from THIS process's environment. The value is
#   never printed, echoed, or logged by this script.
set -eu
DRAFT="$HOME/workspace/goals/glossa-lab-spec-kit-aee-migration-and-indus-program/hidden_files/spec080-migration/glossa-tailnet-forwarder.service"
UNIT=/etc/systemd/system/glossa-tailnet-forwarder.service
ENVFILE=/var/lib/glossa-lab/forwarder.env

if [ -z "${HTTPS_PROXY:-}" ] && [ -z "${https_proxy:-}" ]; then
  echo "FATAL: no proxy env in this process; forwarder cannot derive its tunnel" >&2
  exit 1
fi
PROXYVAL="${HTTPS_PROXY:-$https_proxy}"

sudo -n install -d -m 0755 /var/lib/glossa-lab
# env file: value flows env -> file inside this script only
umask 077
printf 'HTTPS_PROXY=%s\n' "$PROXYVAL" > /tmp/forwarder.env.$$
sudo -n install -m 0600 /tmp/forwarder.env.$$ "$ENVFILE"
rm -f /tmp/forwarder.env.$$
echo "env file installed: $ENVFILE (mode 600, contents not shown)"

# unit: draft + EnvironmentFile injected into [Service]
sed '/^\[Service\]/a EnvironmentFile=/var/lib/glossa-lab/forwarder.env' "$DRAFT" > /tmp/glossa-tailnet-forwarder.service.$$
sudo -n install -m 0644 /tmp/glossa-tailnet-forwarder.service.$$ "$UNIT"
rm -f /tmp/glossa-tailnet-forwarder.service.$$
echo "unit installed: $UNIT"

sudo -n systemctl daemon-reload
sudo -n systemctl enable glossa-tailnet-forwarder
sudo -n systemctl restart glossa-tailnet-forwarder
sleep 2
systemctl is-active glossa-tailnet-forwarder
systemctl is-enabled glossa-tailnet-forwarder
echo "--- health through the forwarder (expect the DESKTOP payload: auth=token) ---"
for i in 1 2 3 4 5 6; do
  if curl -s -m 5 http://127.0.0.1:8001/api/v1/health; then echo; break; fi
  echo "attempt $i: no answer yet"; sleep 3
done
